using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using UnscRelay.Core;
internal static class PlainExportClientChecks
{
 sealed class Server(Guid archive):HttpMessageHandler
 {
  public int Requests;public string Changed="";public bool Failure;public object Envelope=new{version=1,kdf="PBKDF2-SHA256",iterations=600000,salt="AAAAAAAAAAAAAAAAAAAAAA==",iv="AAAAAAAAAAAAAAAA",ciphertext="AAAAAAAAAAAAAAAAAAAAAA=="};
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Requests++;if(request.RequestUri!.Host!="unsc.responda.eu"||request.RequestUri.Scheme!="https"||request.Headers.Authorization?.Parameter!="fixture-access")throw new Exception("Incorrect account transport");if(Failure)return new(HttpStatusCode.ServiceUnavailable){Content=JsonContent.Create(new{error="Synthetic service unavailable"})};if(request.RequestUri.AbsolutePath.EndsWith("/download",StringComparison.Ordinal)){if(request.Method!=HttpMethod.Post)throw new Exception("Incorrect download verb");var body=JsonSerializer.Deserialize<JsonElement>(await request.Content!.ReadAsStringAsync(ct));if(body.GetProperty("revision").GetInt64()!=7||body.GetProperty("code").GetString()!="12345678")throw new Exception("Download context changed");return new(HttpStatusCode.OK){Content=JsonContent.Create(new{archiveId=Changed=="archive"?Guid.NewGuid():archive,archiveOwner=Changed=="owner"?new string('B',64):new string('A',64),revision=Changed=="revision"?8:7,scope=Changed=="scope"?"all":"current",envelope=Changed=="format"?(object)new{version=2}:Envelope})};}return new(HttpStatusCode.OK){Content=JsonContent.Create(new{archiveId=Changed=="archive"?Guid.NewGuid():archive,archiveOwner=new string('A',64),name="Fixture export",revision=Changed=="revision"?0:7,format=1,scope="current"})};}
 }
 public static async Task<int> Run(){var directory=Directory.CreateTempSubdirectory("relay-export-client-");var count=0;void Check(bool value,string text){if(!value)throw new Exception(text);count++;Console.WriteLine("PASS export client: "+text);}try{var archive=Guid.NewGuid();var server=new Server(archive);using var client=new CloudAccountClient(directory.FullName,server);try{await client.ReviewPlainExport(archive,CancellationToken.None);throw new Exception("Disconnected review accepted");}catch(OnlineAccessException){Check(server.Requests==0,"disconnected account cannot begin review");}client.State.Activated=true;client.State.AccessToken="fixture-access";client.State.TokenExpires=DateTimeOffset.UtcNow.AddMinutes(5);var review=await client.ReviewPlainExport(archive,CancellationToken.None);Check(review.Revision==7&&review.ArchiveId==archive,"review validates actual archive identity and revision");var challenge=Guid.NewGuid();var download=await client.DownloadPlainExport(review,challenge,"12345678",CancellationToken.None);Check(download.GetProperty("version").GetInt32()==1,"native transport receives ciphertext only");foreach(var changed in new[]{"archive","owner","revision","scope","format"}){server.Changed=changed;try{await client.DownloadPlainExport(review,challenge,"12345678",CancellationToken.None);throw new Exception("Changed binding accepted: "+changed);}catch(InvalidDataException){Check(true,"changed "+changed+" binding is rejected before decryption");}}server.Changed="";server.Failure=true;var before=server.Requests;try{await client.DownloadPlainExport(review,challenge,"12345678",CancellationToken.None);throw new Exception("Failure accepted");}catch(OnlineAccessException){Check(server.Requests==before+1,"failed sensitive download is never retried automatically");}before=server.Requests;try{await client.DownloadPlainExport(review,challenge,new string('1',33),CancellationToken.None);throw new Exception("Oversized code accepted");}catch(ArgumentException){Check(server.Requests==before,"oversized code rejected before network");}Console.WriteLine("Export client checks: "+count);return 0;}finally{directory.Delete(true);}}
}
